def _archive():
    data = base64.b85decode("".join(_ARCHIVE_B85))
    if hashlib.sha256(data).hexdigest() != _ARCHIVE_SHA256:
        raise RuntimeError("ELSD bundle checksum mismatch")
    return zipfile.ZipFile(io.BytesIO(data))


def _extract(destination):
    destination = Path(destination).expanduser().resolve()
    destination.mkdir(parents=True, exist_ok=True)
    with _archive() as archive:
        for item in archive.infolist():
            path = (destination / item.filename).resolve()
            if not path.is_relative_to(destination):
                raise RuntimeError("Unsafe archive path")
        archive.extractall(destination)
    return destination / "EstimateLink_WQB_Aligned"


def main():
    if len(sys.argv) == 3 and sys.argv[1] == "--extract":
        print(_extract(sys.argv[2]))
        return
    with tempfile.TemporaryDirectory(prefix="elsd_engine_") as temporary:
        research = _extract(temporary) / "research"
        sys.path.insert(0, str(research))
        try:
            sys.argv[0] = str(research / "engine.py")
            runpy.run_path(str(research / "engine.py"), run_name="__main__")
        finally:
            sys.path.remove(str(research))


if __name__ == "__main__":
    main()
